/* ============ EJECUCIÓN / SCHEDULER ============ */
function run(o, forced){
  if(state.paused) return;
  o.api.tick();
  o.cycles++; state.cycles++;
  state.tickTimes.push(Date.now());
  o.card.classList.add('tick'); setTimeout(()=>o.card.classList.remove('tick'), 380);
  o.card.querySelector('.cyc').textContent = o.cycles;
  o.card.querySelector('.last').textContent = 'hace 0s';
  const nd = nodeEls[o.cfg.id]; if(nd){ nd.classList.add('pulse'); setTimeout(()=>nd.classList.remove('pulse'), 450); }
  if(forced || Math.random()<.22) log('SEC-'+p2(o.cfg.id), forced?'ciclo forzado por operador':'ciclo completado · '+o.cfg.name.toLowerCase());
  if(state.chaos && Math.random()<.3){ state.errors++; log('SEC-'+p2(o.cfg.id), pick(['plantilla desalineada','tabla corrupta releída','checksum reintentado','píxel fuera de matriz']),'err'); }
}
setInterval(() => {
  if(state.paused) return;
  const now = performance.now();
  objs.forEach(o => {
    if(now >= o.next){
      run(o,false);
      const base = (o.api.fast? rnd(400,900) : rnd(1600,5200));
      o.next = now + base/state.speed;
    }
  });
}, 160);

