  $('#cycles').textContent = state.cycles.toLocaleString('es-ES');
  $('#errors').textContent = state.errors;
  state.tickTimes = state.tickTimes.filter(t => Date.now()-t < 60000);
  const thr = Math.min(99, state.tickTimes.length);
  const load = Math.min(99, 30 + state.speed*18 + rnd(0,14) + (state.chaos?25:0));
  const q = Math.min(99, rnd(4,20) + (state.paused?40:0));
  const set=(id,v)=>{ const e=$(id); e.style.setProperty('--v',v); e.querySelector('b').textContent=v; };
  set('#gLoad',load); set('#gThr',thr); set('#gQueue',q);
}, 900);

